+  | Asc(p, _)
+  | Projector(_, p)
+  | TupLabel(_, p) => pat_name(p)
+  | Ap(f, _) => pat_name(f)
+  | Tuple([p, ..._]) => pat_name(p)
+  | _ => None
+  };
