+  HazelDB.kv_save(
+    collapse_key(prefix, name),
+    collapse_paths(prefix, name)
+    |> sexp_of_collapse_file
+    |> Sexplib.Sexp.to_string,
+  );
+
+let write_pins =
+    (prefix: string, name: string, pins: list((OutlineTree.path, bool)))
+    : unit =>
+  HazelDB.kv_save(
