+  | None => None
+  | Some(seg) =>
+    let body = {
+      let rec find_mod = (ps: Segment.t) =>
+        switch (ps) {
+        | [] => None
+        | [Piece.Tile(t), ...rest] =>
+          switch (t.label) {
+          | ["module", ..._] =>
+            switch (List.rev(t.children)) {
+            | [def, ..._] =>
+              List.find_map(
+                (p: Piece.t) =>
+                  switch (p) {
