+              )
+            | None => Printf.printf("BENCHSTATICS %s: <no parse>\n", name)
+            }
+          };
+        },
+        ["bench-1k.hz", "bench-2k5.hz", "bench-5k.hz"],
+      )
+    ),
+  ],
+);

